<?php
namespace App\Http\Controllers; use App\Models\{BotPattern,RecordedStroke};
class BotPatternController extends Controller {public function index(){return view('admin.bot-patterns.index',['patterns'=>BotPattern::latest('created_at')->get()]);}public function recordings(){ $groups=RecordedStroke::with('session')->orderByDesc('created_at')->get()->groupBy(fn($s)=>$s->session_id.'|'.$s->player_ip);return view('admin.bot-patterns.recordings',compact('groups'));}public function preview(int $id){$pattern=BotPattern::findOrFail($id);return view('admin.bot-patterns.preview',['title'=>$pattern->name,'strokes'=>$pattern->strokes]);}public function approve(int $id){$first=RecordedStroke::findOrFail($id);$rows=RecordedStroke::where('session_id',$first->session_id)->where('player_ip',$first->player_ip)->orderBy('drawn_at')->get();$base=$rows->first()?->drawn_at; $strokes=$rows->map(fn($s)=>['points'=>$s->points,'color'=>$s->color,'size'=>$s->size,'delay_ms'=>$base?min(3000,max(80,$base->diffInMilliseconds($s->drawn_at))):150])->values()->all();BotPattern::create(['name'=>'Session '.$first->session_id.' / '.substr($first->player_ip,0,18),'source_session_id'=>$first->session_id,'source_ip'=>$first->player_ip,'strokes'=>$strokes,'approved'=>true,'approved_at'=>now()]);return back()->with('message','Recording approved as a bot pattern.');}public function reject(int $id){$first=RecordedStroke::findOrFail($id);RecordedStroke::where('session_id',$first->session_id)->where('player_ip',$first->player_ip)->delete();return back()->with('message','Recording deleted.');}public function destroy(int $id){BotPattern::findOrFail($id)->delete();return back()->with('message','Bot pattern deleted.');}}
